def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, with ties going to the nearest even number.

    Args:
    n (float): The number to round.

    Returns:
    int: The rounded integer.
    """
    if n % 2 != 0 and n - math.floor(n) == 0.5:
        return math.floor(n + 1)
    else:
        return round(n)

