def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    cache = {}
    freq = {}

    class LFUcache:
        def __init__(self, keyFunction=None):
            if maxsize < 1:
                raise ValueError("num must be >= 1")
            if keyFunction is None:
                keyFunction = lambda x: x
            self.cache = {}
            self.freq = {}
            self.size = 0
            self.maxsize = maxsize
            self.keyFunction = keyFunction
            self.order = []

        def __call__(self, key):
            if key in self.cache:
                self.freq[key] += 1
                if self.size > self.maxsize:
                    leastFreq = min(self.freq.values())
                    keys = [k for k, v in self.freq.items() if v == leastFreq]
                    persistentKey = self.order.pop(keys.pop(keys.index(min(keys))))
                    del self.freq[persistentKey]
                    del self.cache[persistentKey]
                    self.size -= 1
                return self.cache[key]
            else:
                key = self.keyFunction(key)
                self.freq[key] = 1
                if self.size < self.maxsize:
                    self.order.append(key)
                else:
                    leastFreq = min(self.freq.values())
                    keys = [k for k, v in self.freq.items() if v == leastFreq]
                    persistentKey = self.order.pop(keys.pop(keys.index(min(keys))))
                    del self.freq[persistentKey]
                    del self.cache[persistentKey]
                    self.order.append(key)
                self.cache[key] = key
                self.size += 1
                return key

        def get(self, key, default=None):
            if key in self.cache:
                self.freq[key] += 1
                if self.size > self.maxsize:
                    leastFreq = min(self.freq.values())
                    keys = [k for k, v in self.freq.items() if v == leastFreq]
                    persistentKey = self.order.pop(keys.pop(keys.index(min(keys))))
                    del self.freq[persistentKey]
                    del self.cache[persistentKey]
                    self.size -= 1
                return self.cache[key]
            else:
                return default

        def keys(self):
            return list(self.order)

        def values(self):
            return values(self.cache.values())

        def items(self):
            return items(self.cache.items())

        def __repr__(self):
            return f"<LFUcache(size={self.size}, maxsize={self.maxsize})>"

