def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """

    if lock is None:
        lock = threading.Lock()

    def decorator(func):
        cache_key = (key(func), cache)
        # Using weakref to automatically remove stale entries from the cache
        cache_entry = weakref.WeakKeyDict()

        @functools.wraps(func)
        def memoized_func(*args, **kwargs):
            if cache_entry.get(*args, None) is None:
                with lock:
                    if cache_entry.get(*args, None) is None:
                        result = func(*args, **kwargs)
                        cache_entry[args] = result
            return cache_entry[args]

        return memoized_func

    return decorator

