def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if isinstance(sequence, tuple):
        return tuple(_normalizeargs(i) for i in sequence)

    elif output is not None:
        output.append(sequence)

    elif isinstance(sequence, Declaration):
        return sequence

    elif isinstance(sequence, tuple):
        return sequence

    elif isinstance(sequence, set):
        return {_normalizeargs(i) for i in sequence if _normalizeargs(i)}

    elif isinstance(sequence, declarbaseset):
        for i in declarbaseset:
            sequence.extend(_normalizeargs(i))

        return sequence

    elif isinstance(sequence, declarbasesetinterface):
        for i in declarbasesetinterface:
            sequence.extend(_normalizeargs(i))

    elif isinstance(sequence, explicitimplsinterface):
        for i in explicitimplsinterface:
            sequence.extend(_normalizeargs(i))

    elif isinstance(sequence, interface):
        return interface

