    if level < 0:
        return result

    deep_result = {}
    for key, value in result.items():
        if isinstance(value, dict):
            sub_result = difference(value, d2.get(key, {}), level - 1)
            if sub_result:
                deep_result[key] = sub_result
        else:
            deep_result[key] = value

    return deep_result

