def _validate_labels(labels):
    """Check that keys and values in the given labels match against their respective
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expressions. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {'['invalid']': 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    if labels is None:
        raise TypeError("labels must be a non-None dictionary")

    if not isinstance(labels, dict):
        raise TypeError("expected a dictionary, but got {}".format(type(labels)))

    errors = []
    for key, value in labels.items():
        if not isinstance(key, str):
            errors.append({'key': key, 'value': 'expected string'})
        if not isinstance(value, (str, list)):
            errors.append({'key': key, 'value': 'expected string or list'})

    potentially_invalid_values = []
    for i in range(len(errors)):
        value = errors[i]['value']
        if isinstance(value, list):
            keys_to_check = [j for j in value if not isinstance(j, (str, list))]  # check if list contains non-str or non-list
            potentially_invalid_values.extend(keys_to_check)

    for i in range(len(errors)):
        value = errors[i]['value']
        if isinstance(value, list):
            messages = []
            for v in value:
                if not isinstance(v, str):
                    messages.append(' expected string')
            if messages:
                errors[i]['value'] = f"[{', '.join(messages)}]"

    if potentially_invalid_values:
        errors.append({'Invalid values': potentially_invalid_values})

    if errors:
        raise ValidationError(errors)

