def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Use regular expressions to replace custom string URL items with values from args
    # This assumes that custom string URL items are in the form {arg}
    pattern = r'{([^}]+)}'
    for match in re.finditer(pattern, url):
        arg = match.group(1)
