    if number < 0:
        raise ValueError("The input number must be non-negative.")

    result = ""
    while number > 0:
        remainder = number % len(alphabet)
        result = alphabet[remainder] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.zfill(padding)

    return result

