def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not archive_path:
        raise ValueError("Archive path is required")

    if not isinstance(archive_path, str):
        raise TypeError("Archive path must be a string")

    if filename is not None and not isinstance(filename, str):
        raise TypeError("Filename must be a string")

    if not isinstance(tmp_path, (PosixPath, str)):
        raise TypeError("Tmp path must be a string or PosixPath")

    archive_name = Path(archive_path).name
    tmp_target_path = Path(tmp_path) / archive_name

    subprocess.run(["unzip", archive_path, "-d", tmp_target_path])
    return str(tmp_target_path.as_uri())

