def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    import re

    # find all tags in the text
    tags = re.findall(r'\{[^}]*\}', text)
    tag_set = set(tags)

    # ignore tags inside code blocks
    blocks = re.compile(r'```.*?```').findall(text)
    for block in blocks:
        for tag in tags:
            if tag in block:
                tag_set.remove(tag)

    # replace tags if specified
    if replacer:
        for tag in tags:
            text = text.replace(tag, replacer(tag))

    return tag_set, text

