def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    with open(plugin_dir / 'plugin.yaml', 'r') as file:
        plugin_spec = yaml.safe_load(file)

    flatten_dict = {}

    def traverse_dict(obj, prefix=''):
        for key in obj:
            full_key = prefix + key if prefix else key
            if isinstance(obj[key], dict):
                traverse_dict(obj[key], full_key + '.')
            else:
                flatten_dict[full_key] = obj[key]

    traverse_dict(plugin_spec)
    return flatten_dict

